import numpy as np

A = ['noop', 'up', 'down', 'left', 'right']

def make(agent=(4, 4), reward=None, mover=None, obstacle=None):
    x = np.zeros(500)
    def setc(r, c, ch, val=1):
        x[(r * 10 + c) * 5 + ch] = val
    # wall border is always obstacle
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                setc(r, c, 3, 1)
    setc(agent[0], agent[1], 0, 1)
    setc(agent[0], agent[1], 4, 1)  # previous frame: agent was here
    if reward is not None:
        setc(reward[0], reward[1], 2, 1)
    if mover is not None:
        setc(mover[0], mover[1], 1, 1)
    if obstacle is not None:
        setc(obstacle[0], obstacle[1], 3, 1)
    return x

conds = [('base', None, None, None)]
for name, pos in [('up', (3, 4)), ('down', (5, 4)), ('left', (4, 3)), ('right', (4, 5))]:
    conds.append(('R_' + name, pos, None, None))
    conds.append(('M_' + name, None, pos, None))
    conds.append(('O_' + name, None, None, pos))

X = np.array([make((4, 4), r, m, o) for _, r, m, o in conds])
Y = forward(X)
base = Y[0]

for (name, _, _, _), y in zip(conds, Y):
    d = y - base
    print(f"{name:7s} argmax={A[int(np.argmax(y))]:5s} "
          f"logits=" + " ".join(f"{v:+.2f}" for v in y) +
          " delta=" + " ".join(f"{v:+.2f}" for v in d))

import numpy as np

def make_input(agent_pos, prev_pos=None):
    x = np.zeros(500)
    # wall border in channel 3
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                x[(r*10 + c)*5 + 3] = 1.0
    if agent_pos is not None:
        r, c = agent_pos
        x[(r*10 + c)*5 + 0] = 1.0
    if prev_pos is not None:
        r, c = prev_pos
        x[(r*10 + c)*5 + 4] = 1.0
    return x

conditions = []
# baseline at (4,4) no previous frame
conditions.append(("agent(4,4) prev none", make_input((4,4), None)))
# previous frame at each neighbor and same cell
for name, pos in [("up",(3,4)), ("down",(5,4)), ("left",(4,3)), ("right",(4,5)), ("same",(4,4))]:
    conditions.append((f"agent(4,4) prev {name}", make_input((4,4), pos)))
# other agent positions with no previous frame
for name, pos in [("(3,3)",(3,3)), ("(5,0)",(5,0)), ("(2,1)",(2,1)), ("(7,4)",(7,4)), ("(3,8)",(3,8)), ("(9,1)",(9,1))]:
    conditions.append((f"agent{name} prev none", make_input(pos, None)))

X = np.array([c[1] for c in conditions])
logits = forward(X)
for (name, _), lg in zip(conditions, logits):
    am = np.argmax(lg)
    print(f"{name}: argmax={am}, logits={np.round(lg,2)}")
